CREATE TABLE IF NOT EXISTS migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE EXTENSION IF NOT EXISTS pg_trgm;
CREATE TABLE categories(id text PRIMARY KEY,name text NOT NULL,position int NOT NULL,enabled boolean NOT NULL DEFAULT true,keywords text[] NOT NULL DEFAULT '{}',priority text NOT NULL DEFAULT 'info' CHECK(priority IN ('info','priority','urgent')));
CREATE TABLE sources(id serial PRIMARY KEY,name text NOT NULL UNIQUE,kind text NOT NULL CHECK(kind IN ('rss','hn','bluesky','reddit','facebook','x')),url text,category text REFERENCES categories(id),enabled boolean NOT NULL DEFAULT true,official boolean NOT NULL DEFAULT false,interval_seconds int NOT NULL DEFAULT 120 CHECK(interval_seconds BETWEEN 30 AND 86400),priority text NOT NULL DEFAULT 'info' CHECK(priority IN ('info','priority','urgent')),status text NOT NULL DEFAULT 'pending',last_check timestamptz,last_success timestamptz,next_poll timestamptz NOT NULL DEFAULT now(),error text,failures int NOT NULL DEFAULT 0,etag text,last_modified text,item_count bigint NOT NULL DEFAULT 0,config jsonb NOT NULL DEFAULT '{}');
CREATE TABLE accounts(id serial PRIMARY KEY,handle text NOT NULL UNIQUE,did text UNIQUE,source_id int REFERENCES sources(id) ON DELETE CASCADE,category text REFERENCES categories(id),enabled boolean NOT NULL DEFAULT true,priority text NOT NULL DEFAULT 'priority' CHECK(priority IN ('info','priority','urgent')),terms text[] NOT NULL DEFAULT '{}',official boolean NOT NULL DEFAULT false,error text);
CREATE TABLE rules(id serial PRIMARY KEY,term text NOT NULL,group_name text NOT NULL DEFAULT 'Geral',category text REFERENCES categories(id),priority text NOT NULL DEFAULT 'info' CHECK(priority IN ('info','priority','urgent')),exclude boolean NOT NULL DEFAULT false,enabled boolean NOT NULL DEFAULT true);
CREATE TABLE stories(id bigserial PRIMARY KEY,source_id int NOT NULL REFERENCES sources(id),external_id text NOT NULL,url text NOT NULL,canonical_url text NOT NULL,title text NOT NULL,summary text NOT NULL DEFAULT '',author text,category text REFERENCES categories(id),priority text NOT NULL CHECK(priority IN ('info','priority','urgent')),status text NOT NULL CHECK(status IN ('official','confirmed','unconfirmed','rumor','corrected')),published_at timestamptz NOT NULL,detected_at timestamptz NOT NULL DEFAULT clock_timestamp(),fingerprint text NOT NULL,cluster_key text NOT NULL,tags text[] NOT NULL DEFAULT '{}',UNIQUE(source_id,external_id));
CREATE INDEX stories_detected_idx ON stories(detected_at DESC,id DESC);
CREATE INDEX stories_category_idx ON stories(category,detected_at DESC);
CREATE INDEX stories_url_idx ON stories(canonical_url);
CREATE INDEX stories_cluster_idx ON stories(cluster_key);
CREATE INDEX stories_fingerprint_idx ON stories(fingerprint);
CREATE INDEX stories_title_trgm ON stories USING gin(title gin_trgm_ops);
CREATE INDEX stories_search_idx ON stories USING gin(to_tsvector('simple',title||' '||summary||' '||coalesce(author,'')));
CREATE TABLE devices(id text PRIMARY KEY,created_at timestamptz DEFAULT now());
CREATE TABLE story_state(device_id text REFERENCES devices(id) ON DELETE CASCADE,story_id bigint REFERENCES stories(id) ON DELETE CASCADE,favorite boolean NOT NULL DEFAULT false,read_at timestamptz,PRIMARY KEY(device_id,story_id));
CREATE INDEX story_state_favorites ON story_state(device_id,favorite);
CREATE TABLE alerts(id bigserial PRIMARY KEY,story_id bigint NOT NULL UNIQUE REFERENCES stories(id) ON DELETE CASCADE,level text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settings(key text PRIMARY KEY,value jsonb NOT NULL);
CREATE TABLE admins(id serial PRIMARY KEY,username text NOT NULL UNIQUE,password_hash text NOT NULL);
CREATE TABLE sessions(token_hash text PRIMARY KEY,admin_id int NOT NULL REFERENCES admins(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL);
CREATE TABLE bootstrap(token_hash text PRIMARY KEY,expires_at timestamptz NOT NULL);
CREATE TABLE collector_state(key text PRIMARY KEY,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit(id bigserial PRIMARY KEY,admin_id int REFERENCES admins(id) ON DELETE SET NULL,action text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
